/bin/bash -lc "mkdir -p public/covers src server tests && python3 - <<'PY'
import urllib.request, concurrent.futures
books = {'creative-act':'9780593652886','midnight-library':'9780525559474','tomorrow':'9780593321201','atomic-habits':'9780735211292','alchemist':'9780061122415','coffee':'9781335430991','psychology-of-money':'9780857197689'}
def fetch(item):
 name,isbn=item
 try:
  req=urllib.request.Request(f'https://covers.openlibrary.org/b/isbn/{isbn}-L.jpg',headers={'User-Agent':'Bookshelf/1.0'})
  data=urllib.request.urlopen(req,timeout=25).read()
  if len(data)>1000:
   open(f'public/covers/{name}.jpg','wb').write(data)
   return name,len(data)
  return name,'missing'
 except Exception as e: return name,str(e)
with concurrent.futures.ThreadPoolExecutor(max_workers=7) as pool:
 for result in pool.map(fetch,books.items()): print(result)
