}
async function stop(){const exited=new Promise(resolve=>server.once('"'exit',resolve));server.kill();await exited;}
try {
 await start();
 const create=await fetch('http://localhost:3101/api/books',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:'Restart check',author:'A Reader',notes:'Kept after restart',status:'reading'})});
 assert.equal(create.status,201);
