 assert.equal(patch.status,200);
 await stop();await start();
 const saved=await fetch("'`http://localhost:3101/api/books/${book.id}`).then(r=>r.json());
 assert.equal(saved.notes,'"'Kept after restart');assert.equal(saved.status,'finished');assert.ok(saved.finishedAt);
 const direct=await fetch("'`http://localhost:3101/books/${book.id}`);
 assert.equal(direct.status,200);assert.ok((await direct.text()).includes('"'<div id=\"root\"></div>'));
 const invalid=await fetch('http://localhost:3101/api/books',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:' ',author:'A Reader',status:'reading'})});assert.equal(invalid.status,400);
 assert.ok(JSON.parse(await readFile(file,'utf8')).some(b=>b.id===book.id));
 console.log('PASS: production API, validation, direct book links, JSON persistence across an actual server restart.');
} finally {if(server?.exitCode===null)await stop();await rm(folder,{recursive:true,force:true});}
